// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { interpolate, interpolateColors, spring, useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
// 1. FONT LOADER
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// 2. SCHEMA


export type RealEstateMarketDataProps = Record<string, any>;

// 3. COMPONENT
const RealEstateMarketData: React.FC<RealEstateMarketDataProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  strokeColor = "#1a1a1a",
  barFillColor = "#e5e5e5",
  accentColor = "#000000",
  durationInSeconds = 10,
  strokeWidth = 2,
  houseScale = 1,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse colors
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const entranceStart = 0;
  const barsStart = 15;
  const nodesStart = 45;
  const glassStart = 80;
  const selectionStart = 140;

  // --- HOUSE ANIMATION (Stroke Draw) ---
  const housePathLength = 300; // approx
  const houseProgress = spring({
    frame: frame - entranceStart,
    fps,
    config: { damping: 200, stiffness: 100 },
    durationInFrames: 60,
  });
  const houseStrokeDashoffset = interpolate(houseProgress, [0, 1], [housePathLength, 0]);

  // --- BARS ANIMATION ---
  // We have 5 bars
  const barHeights = [40, 65, 50, 85, 60]; // Percentages relative to house container
  const barDelays = [0, 5, 2, 8, 4]; // Stagger
  
  // --- NODES ANIMATION ---
  const nodesProgress = spring({
    frame: frame - nodesStart,
    fps,
    config: { damping: 15 },
  });
  
  // --- MAGNIFYING GLASS ANIMATION ---
  const glassProgress = spring({
    frame: frame - glassStart,
    fps,
    config: { damping: 20 },
  });
  
  // Moves from left to right, then stops at the "best" bar (index 3, height 85)
  // X positions logic:
  // House width in viewBox is 60 (20 to 80).
  // Bars are spread within that. 
  // Bar centers approx: 26, 36, 46, 56, 66.
  const glassX = interpolate(
    frame - glassStart,
    [0, 30, 60],
    [20, 66, 56], // Move across then settle on index 3 (56)
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const glassScale = interpolate(
    glassProgress,
    [0, 1],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // --- SELECTION SUCCESS ---
  const successProgress = spring({
    frame: frame - selectionStart,
    fps,
    config: { stiffness: 200, damping: 10 },
  });

  // --- RENDER HELPERS ---
  const viewBoxSize = 100;
  const housePathD = "M 20 40 L 50 15 L 80 40 L 80 80 L 20 80 Z";
  
  // Calculate Node Points for the line chart
  // Mapping barHeights to Y coordinates.
  // House bottom is 80. Top is roughly 20-30 depending on roof.
  // Max bar height (100%) -> Y=30. Min bar height (0%) -> Y=80.
  // Range is 50 units.
  const getBarY = (h: number) => 80 - (h / 100) * 50;
  
  const nodePoints = barHeights.map((h, i) => {
    const x = 26 + i * 10; // 26, 36, 46, 56, 66
    const y = getBarY(h);
    return { x, y };
  });

  const polylinePoints = nodePoints.map(p => `${p.x},${p.y}`).join(" ");

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <svg
          width={width * 0.6}
          height={height * 0.6}
          viewBox={`0 0 ${viewBoxSize} ${viewBoxSize}`}
          style={{ overflow: "visible" }}
        >
          <defs>
            <clipPath id="houseClip">
              <path d={housePathD} />
            </clipPath>
          </defs>

          {/* GROUP: Everything scaled/centered */}
          <g transform={`scale(${houseScale})`} style={{ transformOrigin: "center" }}>
            
            {/* 1. CHART BARS (Clipped by House) */}
            <g clipPath="url(#houseClip)">
              {barHeights.map((h, i) => {
                const barProgress = spring({
                  frame: frame - barsStart - barDelays[i],
                  fps,
                  config: { damping: 12 },
                });
                
                // Bar Highlight on Success (Index 3 is the winner)
                const isWinner = i === 3;
                const barColor = isWinner 
                  ? interpolateColors(successProgress, [0, 1], [barFillColor, accentColor]) // Use interpolateColors for string output
                  : barFillColor;

                const currentHeight = interpolate(barProgress, [0, 1], [0, (h / 100) * 50]);
                
                return (
                  <rect
                    key={i}
                    x={22 + i * 10}
                    y={80 - currentHeight}
                    width={8}
                    height={currentHeight}
                    fill={barColor}
                    style={{ opacity: barProgress }}
                  />
                );
              })}
            </g>

            {/* 2. HOUSE OUTLINE */}
            <path
              d={housePathD}
              fill="none"
              stroke={strokeColor}
              strokeWidth={strokeWidth}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={housePathLength}
              strokeDashoffset={houseStrokeDashoffset}
            />

            {/* 3. DATA NODES & LINE */}
            <g style={{ opacity: nodesProgress }}>
              <polyline
                points={polylinePoints}
                fill="none"
                stroke={strokeColor}
                strokeWidth={strokeWidth * 0.5}
                strokeDasharray="2 2"
                opacity={0.6}
              />
              {nodePoints.map((p, i) => (
                <circle
                  key={i}
                  cx={p.x}
                  cy={p.y}
                  r={strokeWidth * 0.8}
                  fill={backgroundColor}
                  stroke={strokeColor}
                  strokeWidth={strokeWidth * 0.5}
                />
              ))}
            </g>

            {/* 4. MAGNIFYING GLASS */}
            {frame > glassStart && (
               <g 
                transform={`translate(${glassX}, ${getBarY(85) - 10}) scale(${glassScale})`} // Target height of best bar
                style={{ transformOrigin: "0 0" }} // Pivot at the glass lens center
               >
                 {/* Lens */}
                 <circle
                   cx={0}
                   cy={0}
                   r={8}
                   fill={`${backgroundColor}88`} // Semi-transparent lens
                   stroke={strokeColor}
                   strokeWidth={strokeWidth}
                 />
                 {/* Handle */}
                 <line
                   x1={5}
                   y1={5}
                   x2={12}
                   y2={12}
                   stroke={strokeColor}
                   strokeWidth={strokeWidth}
                   strokeLinecap="round"
                 />
                 
                 {/* Success Indicator (Checkmark inside lens) */}
                 <g style={{ opacity: successProgress, transform: "scale(" + successProgress + ")", transformOrigin: "center" }}>
                    <path
                      d="M -3 0 L -1 2 L 3 -2"
                      fill="none"
                      stroke={accentColor}
                      strokeWidth={strokeWidth}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                 </g>
               </g>
            )}

            {/* Text Label: "Optimal Deal" */}
            <foreignObject x={0} y={90} width={100} height={20} style={{ opacity: successProgress }}>
                <div style={{ 
                    fontFamily: "Inter", 
                    fontSize: "4px", 
                    color: strokeColor, 
                    textAlign: "center",
                    fontWeight: 600,
                    textTransform: "uppercase",
                    letterSpacing: "1px"
                }}>
                    Optimal Deal Found
                </div>
            </foreignObject>
            
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default RealEstateMarketData;